/// Go `genVecFromConstExpr`: evaluates the constant once and fills `n` rows.
// glue: N4 §3 runtime support of the generated drivers (M-EVAL)
pub fn fill_constant(
    ctx: &dyn EvalContext,
    st: &EvalState,
    expr: &Expr,
    as_type: EvalType,
    n: usize,
    col: &mut Column,
) -> Result<(), Error> {
    if n == 0 {
        // Go: genVecFromConstExpr returns before evaluating the constant (`result.Reset`), so
        // an empty input never sees the constant's errors or warnings.
        match as_type {
            ETInt => col.resize_int64(0, false),
            ETReal => col.resize_float64(0, false),
            ETDecimal => col.resize_decimal(0, false),
            ETString => col.reserve_string(0),
            ETDatetime | ETTimestamp => col.resize_time(0, false),
            ETDuration => col.resize_go_duration(0, false),
            ETJson => col.reserve_json(0),
            ETVectorFloat32 => col.reserve_vector_float32(0),
            _ => {}
        }
        return Ok(());
    }
    let row = Row::default();
    match as_type {
        ETInt => {
            let v = expr.eval_int(ctx, st, row)?;
            col.resize_int64(n, v.is_none());
            if let Some(v) = v {
                for x in col.int64s_mut() {
                    *x = I64::new(v);
                }
            }
        }
        ETReal => {
            let v = expr.eval_real(ctx, st, row)?;
            col.resize_float64(n, v.is_none());
            if let Some(v) = v {
                for x in col.float64s_mut() {
                    *x = F64::new(v);
                }
            }
        }
        ETDecimal => {
            let v = expr.eval_decimal(ctx, st, row)?;
            col.resize_decimal(n, v.is_none());
            if let Some(v) = v {
                let w = v.as_wire();
                for x in col.decimals_mut() {
                    *x = w;
                }
            }
        }
        ETString => {
            let v = expr.eval_string(ctx, st, row)?;
            col.reserve_string(n);
            for _ in 0..n {
                match &v {
                    Some(b) => col.append_bytes(b),
                    None => col.append_null(),
                }
            }
        }
        ETDatetime | ETTimestamp => {
            let v = expr.eval_time(ctx, st, row)?;
            col.resize_time(n, v.is_none());
            if let Some(v) = v {
                let w = U64::new(v.raw().0);
                for x in col.times_mut() {
                    *x = w;
                }
            }
        }
        ETDuration => {
            let v = expr.eval_duration(ctx, st, row)?;
            col.resize_go_duration(n, v.is_none());
            if let Some(v) = v {
                for x in col.go_durations_mut() {
                    *x = I64::new(v.duration);
                }
            }
        }
        ETJson => {
            let v = expr.eval_json(ctx, st, row)?;
            col.reserve_json(n);
            for _ in 0..n {
                match &v {
                    Some(j) => col.append_json(j),
                    None => col.append_null(),
                }
            }
        }
        ETVectorFloat32 => {
            let v = expr.eval_vector_float32(ctx, st, row)?;
            col.reserve_vector_float32(n);
            for _ in 0..n {
                match &v {
                    Some(x) => col.append_vector_float32(x),
                    None => col.append_null(),
                }
            }
        }
        other => {
            return Err(Error::plain(format!(
                "vector evaluation of a constant as {} is not ported yet",
                other.0
            )));
        }
    }
    Ok(())
}
